"""WebSocket fan-out and notifier composition.The hazard this module exists to eliminate------------------------------------------A single browser tab on a hotel Wi-Fi connection must never slow down betevaluation. If the broadcaster awaited ``websocket.send_text`` inline, one slowTCP receiver would apply backpressure all the way up through the orchestrator'snotification step, into its semaphore, and eventually into the Redis consumer,which would stop acknowledging. A frontend client would be able to stall thetrading pipeline.The queue-per-client pattern severs that path completely:* **Broadcast is synchronous.** ``put_nowait`` into each client's bounded queue.  It performs no network I/O and cannot await, so its cost is O(clients) of  pure memory operations regardless of how slow any client is.* **Delivery is per-client.** Each client owns a dedicated sender task that  drains its own queue. A blocked send blocks exactly one task.* **Overflow is bounded and visible.** A full queue drops its oldest message  and counts it. A client that keeps overflowing is disconnected, because a  client permanently missing messages is worse than a client that reconnects  and resynchronises.Serialisation happens **once per broadcast**, not once per client. Encoding thesame recommendation twenty times for twenty tabs is pure waste on a path thatruns on every evaluation cycle."""from __future__ import annotationsimport asyncioimport contextlibimport timeimport uuidfrom collections.abc import Sequencefrom dataclasses import dataclass, fieldfrom datetime import datetimefrom enum import StrEnumfrom typing import Any, Finalimport structlogfrom fastapi import WebSocketfrom pydantic import BaseModel, ConfigDict, Fieldfrom starlette.websockets import WebSocketStatefrom betdoc.application.ports.notifiers import (    DebounceDecision,    DebounceReason,    NotificationChannel,    NotificationDebouncer,    RecommendationNotifier,    recommendation_dedupe_key,)from betdoc.domain.intelligence.account_models import utc_nowfrom betdoc.domain.intelligence.advisor_models import (    ActionType,    SessionForecast,    TwinRecommendation,)__all__ = [    "AlwaysAllowDebouncer",    "BroadcasterConfig",    "ClientSnapshot",    "CompositeNotifier",    "WebsocketBroadcaster",    "WsMessage",    "WsMessageType",]_log: Final[structlog.stdlib.BoundLogger] = structlog.get_logger(    component="presentation.api.broadcaster")class WsMessageType(StrEnum):    """Discriminator for every frame the server sends.    A typed discriminator on the wire lets the frontend switch on message kind    without inspecting payload shape, which keeps the client from breaking when    a payload gains a field.    """    HELLO = "hello"    RECOMMENDATION = "recommendation"    REJECTION_BATCH = "rejection_batch"    FORECAST = "forecast"    HEARTBEAT = "heartbeat"    SYSTEM = "system"class WsMessage(BaseModel):    """Envelope for every outbound frame.    Mirrors the bus's :class:`EventEnvelope` deliberately: ``trace_id`` on the    wire means a support question about something a user saw in the dashboard    can be traced straight back through the orchestrator to the originating    odds tick.    """    model_config = ConfigDict(frozen=True, extra="forbid", validate_default=True)    type: WsMessageType    sent_at: datetime = Field(default_factory=utc_now)    trace_id: str = Field(default="", max_length=64)    sequence: int = Field(default=0, ge=0)    payload: dict[str, Any] = Field(default_factory=dict)    def encode(self) -> str:        """Serialise to a JSON string.        Note on the API: Pydantic V2's ``model_dump_json()`` is *already* JSON        mode and accepts no ``mode`` argument. Passing ``mode="json"`` to it        raises ``TypeError``. The ``mode="json"`` keyword belongs to        ``model_dump()``, which is how nested domain models are coerced into        JSON-safe primitives before landing in :attr:`payload`. Both halves of        that contract are exercised here: nested models are dumped with        ``mode="json"``, and the envelope is stringified with        ``model_dump_json()``.        """        return self.model_dump_json()    @classmethod    def of(        cls,        message_type: WsMessageType,        model: BaseModel | None = None,        *,        trace_id: str = "",        sequence: int = 0,        extra: dict[str, Any] | None = None,    ) -> WsMessage:        """Build an envelope from a domain model, JSON-coercing enums and dates."""        payload: dict[str, Any] = model.model_dump(mode="json") if model is not None else {}        if extra:            payload.update(extra)        return cls(            type=message_type,            trace_id=trace_id,            sequence=sequence,            payload=payload,        )class AlwaysAllowDebouncer(NotificationDebouncer):    """Pass-through gate for machine-consumed channels.    The console debounces because a human reads it and alert fatigue is real.    A WebSocket feed is consumed by software: suppressing frames here would    make the dashboard show a stale market while the engine acts on a fresh    one, and presentation-level deduplication belongs in the client where it    can be undone by the user.    """    __slots__ = ()    def evaluate(        self, recommendation: TwinRecommendation, *, now: datetime | None = None    ) -> DebounceDecision:        return DebounceDecision(            allow=True,            reason=DebounceReason.FIRST_SEEN,            dedupe_key=recommendation_dedupe_key(recommendation),            detail="machine-consumed channel; deduplication is the client's concern",        )    def record_delivery(        self, recommendation: TwinRecommendation, *, now: datetime | None = None    ) -> None:        return None    def prune(self, *, now: datetime | None = None) -> int:        return 0    @property    def tracked_keys(self) -> int:        return 0class BroadcasterConfig(BaseModel):    """Per-client buffering and slow-client policy."""    model_config = ConfigDict(frozen=True, extra="forbid", validate_default=True)    client_queue_size: int = Field(        default=256,        ge=8,        le=100_000,        description=(            "Bounded per client. This is the memory ceiling that makes a slow "            "client an isolated problem rather than a process-wide one."        ),    )    max_clients: int = Field(        default=64,        ge=1,        le=10_000,        description="Connection cap. Fan-out is O(clients) on the hot path.",    )    max_consecutive_drops: int = Field(        default=64,        ge=1,        le=100_000,        description=(            "Drops before a client is disconnected. A client permanently "            "behind is showing a false picture of the market, which is more "            "dangerous than forcing it to reconnect and resynchronise."        ),    )    heartbeat_seconds: float = Field(        default=15.0,        gt=0.0,        le=300.0,        description=(            "Idle interval after which a heartbeat is sent. Detects a TCP "            "connection that is dead but not closed, which otherwise leaks a "            "task and a queue for the lifetime of the process."        ),    )    send_timeout_seconds: float = Field(default=5.0, gt=0.0, le=60.0)@dataclass(slots=True)class _ClientChannel:    """One connected client: its socket, its queue, and its sender task."""    client_id: str    websocket: WebSocket    queue: asyncio.Queue[str]    connected_at: float    task: asyncio.Task[None] | None = None    sent: int = 0    dropped: int = 0    consecutive_drops: int = 0    closing: bool = False    labels: dict[str, str] = field(default_factory=dict)class ClientSnapshot(BaseModel):    """Observable state of one client, for the health endpoint."""    model_config = ConfigDict(frozen=True, extra="forbid")    client_id: str    connected_seconds: float = Field(ge=0.0)    queue_depth: int = Field(ge=0)    sent: int = Field(ge=0)    dropped: int = Field(ge=0)    consecutive_drops: int = Field(ge=0)class WebsocketBroadcaster(RecommendationNotifier):    """Fans Twin output out to connected WebSocket clients, never blocking.    Implements :class:`RecommendationNotifier`, so the orchestrator cannot tell    it apart from the console notifier. Every ``notify_*`` method completes in    bounded time with no network await, which is the whole contract.    """    __slots__ = ("_clients", "_config", "_lock", "_sequence", "_total_dropped")    def __init__(        self,        config: BroadcasterConfig | None = None,        debouncer: NotificationDebouncer | None = None,    ) -> None:        super().__init__(NotificationChannel.WEBSOCKET, debouncer or AlwaysAllowDebouncer())        self._config = config or BroadcasterConfig()        self._clients: dict[str, _ClientChannel] = {}        self._lock = asyncio.Lock()        self._sequence = 0        self._total_dropped = 0    # ------------------------------ lifecycle ----------------------------- #    async def start(self) -> None:        """No global resources to acquire. Present to satisfy the port."""        _log.info(            "broadcaster.started",            client_queue_size=self._config.client_queue_size,            max_clients=self._config.max_clients,            heartbeat_seconds=self._config.heartbeat_seconds,        )    async def close(self) -> None:        """Disconnect every client and await its sender task.        Awaiting rather than fire-and-forget cancelling matters: an abandoned        sender task holding a half-written frame leaves the peer waiting on a        socket that will never complete, and leaks the task until process exit.        """        async with self._lock:            channels = list(self._clients.values())            self._clients.clear()        for channel in channels:            channel.closing = True            if channel.task is not None:                channel.task.cancel()        for channel in channels:            if channel.task is not None:                with contextlib.suppress(asyncio.CancelledError, Exception):                    await channel.task            with contextlib.suppress(Exception):                if channel.websocket.client_state is WebSocketState.CONNECTED:                    await channel.websocket.close(code=1001, reason="server shutdown")        _log.info(            "broadcaster.closed",            clients_disconnected=len(channels),            total_dropped=self._total_dropped,        )    # ---------------------------- registration ---------------------------- #    async def register(        self, websocket: WebSocket, *, labels: dict[str, str] | None = None    ) -> str | None:        """Adopt an already-accepted socket. Returns its client id, or ``None``.        Returns ``None`` when the connection cap is reached, so the router can        close with an explicit policy code rather than silently accepting a        client that will never be served.        """        async with self._lock:            if len(self._clients) >= self._config.max_clients:                _log.warning(                    "broadcaster.rejected_client",                    reason="max_clients",                    max_clients=self._config.max_clients,                )                return None            client_id = uuid.uuid4().hex[:12]            channel = _ClientChannel(                client_id=client_id,                websocket=websocket,                queue=asyncio.Queue(maxsize=self._config.client_queue_size),                connected_at=time.monotonic(),                labels=dict(labels or {}),            )            self._clients[client_id] = channel        channel.task = asyncio.create_task(            self._sender_loop(channel), name=f"ws-sender:{client_id}"        )        self._enqueue(            channel,            WsMessage.of(                WsMessageType.HELLO,                extra={                    "client_id": client_id,                    "heartbeat_seconds": self._config.heartbeat_seconds,                    "queue_capacity": self._config.client_queue_size,                },            ).encode(),        )        _log.info(            "broadcaster.client_registered",            client_id=client_id,            total_clients=len(self._clients),            labels=channel.labels,        )        return client_id    async def unregister(self, client_id: str) -> None:        """Remove a client and stop its sender task. Idempotent."""        async with self._lock:            channel = self._clients.pop(client_id, None)        if channel is None:            return        channel.closing = True        if channel.task is not None:            channel.task.cancel()            with contextlib.suppress(asyncio.CancelledError, Exception):                await channel.task        _log.info(            "broadcaster.client_unregistered",            client_id=client_id,            sent=channel.sent,            dropped=channel.dropped,            connected_seconds=round(time.monotonic() - channel.connected_at, 3),        )    @property    def client_count(self) -> int:        return len(self._clients)    def snapshot(self) -> tuple[ClientSnapshot, ...]:        """Per-client state for the health endpoint."""        now = time.monotonic()        return tuple(            ClientSnapshot(                client_id=channel.client_id,                connected_seconds=round(now - channel.connected_at, 3),                queue_depth=channel.queue.qsize(),                sent=channel.sent,                dropped=channel.dropped,                consecutive_drops=channel.consecutive_drops,            )            for channel in self._clients.values()        )    # ------------------------------ notifier ------------------------------ #    async def notify_recommendation(        self, recommendation: TwinRecommendation, *, now: datetime | None = None    ) -> DebounceDecision:        """Enqueue an actionable bet for every client. Never awaits the network."""        decision = self._debouncer.evaluate(recommendation, now=now)        if not decision.allow:            return decision        self._broadcast(            WsMessageType.RECOMMENDATION,            recommendation,            trace_id=recommendation.trace_id,        )        self._debouncer.record_delivery(recommendation, now=now)        return decision    async def notify_rejections(        self,        rejections: Sequence[TwinRecommendation],        *,        now: datetime | None = None,    ) -> int:        """Enqueue refusals as one batch frame.        Batched rather than one frame each. A session that refuses thirty        candidates would otherwise consume thirty queue slots per client and        push genuinely actionable frames out of a bounded buffer.        """        if not rejections:            return 0        trace_id = rejections[0].trace_id        payload = {            "count": len(rejections),            "rejections": [item.model_dump(mode="json") for item in rejections],        }        self._broadcast_raw(            WsMessage(                type=WsMessageType.REJECTION_BATCH,                trace_id=trace_id,                sequence=self._next_sequence(),                payload=payload,            )        )        return len(rejections)    async def notify_forecast(        self, forecast: SessionForecast, *, now: datetime | None = None    ) -> None:        self._broadcast(WsMessageType.FORECAST, forecast, trace_id=forecast.trace_id)    # ------------------------------ internals ----------------------------- #    def _next_sequence(self) -> int:        self._sequence += 1        return self._sequence    def _broadcast(self, message_type: WsMessageType, model: BaseModel, *, trace_id: str) -> None:        self._broadcast_raw(            WsMessage.of(                message_type,                model,                trace_id=trace_id,                sequence=self._next_sequence(),            )        )    def _broadcast_raw(self, message: WsMessage) -> None:        """Encode once, then enqueue the same string for every client.        Synchronous by design. No ``await`` appears anywhere in this path, so        the orchestrator's notification step is bounded by memory operations        and is entirely independent of every client's network speed.        """        if not self._clients:            return        encoded = message.encode()        for channel in list(self._clients.values()):            self._enqueue(channel, encoded)    def _enqueue(self, channel: _ClientChannel, encoded: str) -> None:        """Non-blocking enqueue with drop-oldest overflow.        Dropping the oldest is correct for a live market view: the newest        state is the only one worth rendering, and a client shown a queue of        stale recommendations is worse off than one shown a gap.        """        if channel.closing:            return        try:            channel.queue.put_nowait(encoded)        except asyncio.QueueFull:            with contextlib.suppress(asyncio.QueueEmpty):                channel.queue.get_nowait()                channel.queue.task_done()            channel.dropped += 1            channel.consecutive_drops += 1            self._total_dropped += 1            try:                channel.queue.put_nowait(encoded)            except asyncio.QueueFull:  # pragma: no cover - a slot was just freed                return            if channel.consecutive_drops >= self._config.max_consecutive_drops:                _log.warning(                    "broadcaster.evicting_slow_client",                    client_id=channel.client_id,                    dropped=channel.dropped,                    consecutive_drops=channel.consecutive_drops,                    detail="client cannot keep up; forcing reconnect and resync",                )                channel.closing = True                if channel.task is not None:                    channel.task.cancel()    async def _sender_loop(self, channel: _ClientChannel) -> None:        """Drain one client's queue. The only place a network send is awaited.        Idle time is converted into a heartbeat via the ``wait_for`` timeout,        which is what surfaces a half-open TCP connection instead of leaking        this task and its queue until the process exits.        """        log = _log.bind(client_id=channel.client_id)        try:            while not channel.closing:                try:                    payload = await asyncio.wait_for(                        channel.queue.get(),                        timeout=self._config.heartbeat_seconds,                    )                except TimeoutError:                    payload = WsMessage(                        type=WsMessageType.HEARTBEAT,                        sequence=self._next_sequence(),                    ).encode()                else:                    channel.queue.task_done()                if channel.websocket.client_state is not WebSocketState.CONNECTED:                    break                await asyncio.wait_for(                    channel.websocket.send_text(payload),                    timeout=self._config.send_timeout_seconds,                )                channel.sent += 1                channel.consecutive_drops = 0        except asyncio.CancelledError:            raise        except TimeoutError:            log.warning("broadcaster.send_timeout", sent=channel.sent)        except Exception as exc:            log.info(                "broadcaster.client_send_failed",                error=type(exc).__name__,                detail=str(exc)[:200],            )        finally:            channel.closing = Trueclass CompositeNotifier(RecommendationNotifier):    """Fans one Twin result out to several channels concurrently.    Exists because the orchestrator accepts exactly one notifier, and that is    the right shape: it should not know how many places its output goes.    Two properties the fan-out must preserve:    * **Fault isolation.** ``asyncio.gather(..., return_exceptions=True)``      throughout. A dead WebSocket must not stop the console from rendering,      and neither must stop the orchestrator.    * **No double debouncing.** Each child applies its own policy, so this      class carries a pass-through gate and delegates to each child's      ``notify_*`` rather than reusing the base-class session helper.    """    __slots__ = ("_notifiers",)    def __init__(self, *notifiers: RecommendationNotifier) -> None:        if not notifiers:            msg = "CompositeNotifier requires at least one child notifier"            raise ValueError(msg)        super().__init__(NotificationChannel.CONSOLE, AlwaysAllowDebouncer())        self._notifiers: tuple[RecommendationNotifier, ...] = notifiers    @property    def children(self) -> tuple[RecommendationNotifier, ...]:        return self._notifiers    async def start(self) -> None:        await self._fan_out("start", *(child.start() for child in self._notifiers))    async def close(self) -> None:        """Close every child, even if an earlier one raised."""        await self._fan_out("close", *(child.close() for child in self._notifiers))    async def notify_recommendation(        self, recommendation: TwinRecommendation, *, now: datetime | None = None    ) -> DebounceDecision:        """Deliver to all children; report allowed if any child delivered.        The aggregate decision is what the orchestrator counts, so ``allow``        means "reached at least one channel". Reporting suppression because the        console debounced would understate delivery when the dashboard did in        fact receive the frame.        """        results = await asyncio.gather(            *(child.notify_recommendation(recommendation, now=now) for child in self._notifiers),            return_exceptions=True,        )        decisions = [item for item in results if isinstance(item, DebounceDecision)]        self._log_failures("notify_recommendation", results)        allowed = next((item for item in decisions if item.allow), None)        if allowed is not None:            return allowed        if decisions:            return decisions[0]        return DebounceDecision(            allow=False,            reason=DebounceReason.SUPPRESSED_DUPLICATE,            dedupe_key=recommendation_dedupe_key(recommendation),            detail="every child notifier failed",        )    async def notify_rejections(        self,        rejections: Sequence[TwinRecommendation],        *,        now: datetime | None = None,    ) -> int:        results = await asyncio.gather(            *(child.notify_rejections(rejections, now=now) for child in self._notifiers),            return_exceptions=True,        )        self._log_failures("notify_rejections", results)        counts = [item for item in results if isinstance(item, int)]        return max(counts, default=0)    async def notify_forecast(        self, forecast: SessionForecast, *, now: datetime | None = None    ) -> None:        results = await asyncio.gather(            *(child.notify_forecast(forecast, now=now) for child in self._notifiers),            return_exceptions=True,        )        self._log_failures("notify_forecast", results)    async def notify_session(        self,        *,        forecast: SessionForecast,        recommendations: Sequence[TwinRecommendation],        now: datetime | None = None,    ) -> tuple[int, int]:        """Delegate whole sessions so each child applies its own debouncer.        Overridden rather than inherited on purpose. The base implementation        would iterate recommendations here and call each child once per item,        collapsing the children's independent batching, which matters because        the console renders rejections as a single table and the broadcaster        sends them as a single frame.        """        results = await asyncio.gather(            *(                child.notify_session(forecast=forecast, recommendations=recommendations, now=now)                for child in self._notifiers            ),            return_exceptions=True,        )        self._log_failures("notify_session", results)        delivered = 0        rejected = 0        for item in results:            if isinstance(item, tuple):                delivered = max(delivered, item[0])                rejected = max(rejected, item[1])        return delivered, rejected    @staticmethod    def _log_failures(operation: str, results: Sequence[object]) -> None:        for result in results:            if isinstance(result, BaseException):                _log.warning(                    "composite_notifier.child_failed",                    operation=operation,                    error=type(result).__name__,                    detail=str(result)[:300],                )    async def _fan_out(self, operation: str, *coros: Any) -> None:        results = await asyncio.gather(*coros, return_exceptions=True)        self._log_failures(operation, results)    @staticmethod    def actionable_count(recommendations: Sequence[TwinRecommendation]) -> int:        return sum(1 for item in recommendations if item.action_type is not ActionType.PASS)